/* Read/copy only. Never evaluate code or accept a key, never request model endpoints. */
(function(){'use strict';const nav=Array.from(document.querySelectorAll('aside nav a'));function revealHash(){let id;try{id=decodeURIComponent(location.hash.slice(1));}catch{return;}if(!id)return;const target=document.getElementById(id);if(!target)return;for(let p=target.parentElement;p;p=p.parentElement)if(p.tagName==='DETAILS')p.open=true;for(const a of nav){if(a.getAttribute('href')==='#'+id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');}if(id.startsWith('source-')){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});target.scrollIntoView({block:'start'});}}window.addEventListener('hashchange',revealHash);revealHash();const menu=document.querySelector('.chapter-menu');if(menu&&window.matchMedia?.('(max-width:760px)').matches)menu.open=false;for(const button of document.querySelectorAll('[data-copy]'))button.addEventListener('click',async()=>{const code=document.getElementById(button.dataset.copy),status=document.getElementById(button.dataset.copy+'-status');if(!code||!status)return;try{if(!navigator.clipboard?.writeText)throw Error('unavailable');await navigator.clipboard.writeText(code.textContent);status.textContent='已复制。请先核对费用、权限和停止条件，再由你自行执行。';}catch{status.textContent='浏览器未允许复制，请选中代码手动复制。本站没有执行代码。';}});})();
